import { strings } from "../lib/i18n";

/* THE CATALOG.
   ────────────────────────────────────────────────────────────────────────
   English is the source and the fallback. Every other language is written
   AS that language — not as English rearranged — because her voice is the
   product and a literal "the road closes here" would read like a parking
   sign. Nine in all: en, es, pt-BR, id, fr, de, it, ja, ko.

   Two rules that hold across all of them:
   · the machine speaks in caps and stays short; she speaks in sentences
   · postal words stay postal — carta, matasellos, tarifa */

