    /* ── help / write-to-us ── */
    "hp.title": "HOW IT WORKS",
    "hp.intro": "Most questions here are really a rule nobody told you yet. So — the rules.",
    "hp.q1": "How does a letter find someone?",
    "hp.a1": "Nothing you write is broadcast. {wren} reads how you write — rhythm, sentence shape, the words you reach for — and carries your letter to the stranger whose writing sits closest to yours. You are matched by voice, never by age, location, or a photo.",
    "hp.q2": "Why can't I see who wrote this?",
    "hp.a2": "Because you haven't earned each other's names yet, and neither has anyone else. Everyone here is anonymous until two people decide otherwise.",
    "hp.q3": "How do names get traded?",
    "hp.a3": "From five letters each, either of you may enclose your name. Nothing happens until the other does the same — then {wren} carries both across at once. If one of you never signs, you stay lovely strangers, and that's allowed.",
    "hp.q4": "What is my aura?",
    "hp.a4": "Nine signals in your writing — how you open, how long your lines run, where you put feeling. Each one locks only when there's enough evidence to trust it, which is why it fills slowly and why nothing is claimed early.",
    "hp.q5": "Does anyone read my sealed pages?",
    "hp.a5": "No, and not in the way most apps mean it. Your sealed journal never leaves this phone. It isn't uploaded, isn't backed up to us, and is deliberately left out of the matching entirely — so it cannot reach a stranger even by accident. {wren} doesn't read them either.",
    "hp.q6": "Why is everything so slow?",
    "hp.a6": "Nothing here is throttled. {wren} leaves the second you press send. What takes days is the person at the other end, living their life — and that is the product, not a delay we could sell you out of.",
    "hp.q7": "Someone was cruel. What do I do?",
    "hp.a7": "Open the ⋯ on their letter. Report sends it to us; block closes the road both ways and can be undone in Settings, under Blocked & reported. Repeated reports remove a writer from Kindredly.",
    "hp.q8": "What happens if I delete my account?",
    "hp.a8": "Your letters stay out in the world, unsigned — a kindred keeps what you wrote them, and nothing traces back to you. Your sealed pages never left this phone, so they stay. Everything else goes, for good.",
    "wu.title": "WRITE TO US",
    "wu.intro": "Everyone else here gets a letter. So do we — tell us anything.",
    "wu.ph": "write to us…",
    "wu.addrLabel": "WHERE TO WRITE BACK — OPTIONAL",
    "wu.addrPh": "an address, if you want an answer",
    "wu.addrHint": "Leave it blank and this stays anonymous, like everything else here — but then we can't write back.",
    "wu.fail": "IT DIDN'T GO OUT. TRY AGAIN IN A MOMENT.",
    "wu.send": "GIVE IT TO {wren}",
