    /* ── help / write-to-us ── */
    "hp.title": "COMO FUNCIONA",
    "hp.intro": "Quase toda pergunta aqui é, na verdade, uma regra que ninguém te contou. Então — as regras.",
    "hp.q1": "Como uma carta encontra alguém?",
    "hp.a1": "Nada do que você escreve é transmitido. {wren} lê como você escreve — o ritmo, a forma das frases, as palavras que você busca — e leva sua carta ao estranho cuja escrita fica mais perto da sua. Você é combinado pela voz, nunca por idade, local ou uma foto.",
    "hp.q2": "Por que não vejo quem escreveu isto?",
    "hp.a2": "Porque vocês ainda não conquistaram o nome um do outro, e ninguém mais também. Aqui todos são anônimos até que duas pessoas decidam o contrário.",
    "hp.q3": "Como os nomes são trocados?",
    "hp.a3": "A partir de cinco cartas de cada lado, qualquer um de vocês pode incluir o nome. Nada acontece até o outro fazer o mesmo — então {wren} leva os dois de uma vez. Se um nunca assina, vocês seguem belos estranhos, e tudo bem.",
    "hp.q4": "O que é a minha aura?",
    "hp.a4": "Nove sinais na sua escrita — como você começa, o comprimento das suas linhas, onde você coloca sentimento. Cada um só trava quando há evidência suficiente para confiar nele, por isso ele se enche devagar e por isso nada é afirmado cedo.",
    "hp.q5": "Alguém lê minhas páginas seladas?",
    "hp.a5": "Não, e não no sentido que a maioria dos apps quer dizer. Seu diário selado nunca sai deste telefone. Não é enviado, não é copiado para nós e fica deliberadamente fora do emparelhamento — então não chega a um estranho nem por acidente. {wren} também não as lê.",
    "hp.q6": "Por que tudo é tão lento?",
    "hp.a6": "Nada aqui é limitado. {wren} parte no segundo em que você aperta enviar. O que leva dias é a pessoa do outro lado, vivendo a vida — e isso é o produto, não um atraso do qual poderíamos te vender a saída.",
    "hp.q7": "Alguém foi cruel. O que eu faço?",
    "hp.a7": "Abra os ⋯ na carta dela. Denunciar envia para nós; bloquear fecha o caminho dos dois lados e pode ser desfeito em Ajustes, em Bloqueados e denunciados. Denúncias repetidas removem um escritor do Kindredly.",
    "hp.q8": "O que acontece se eu excluir minha conta?",
    "hp.a8": "Suas cartas ficam pelo mundo, sem assinatura — um afim guarda o que você escreveu, e nada leva de volta a você. Suas páginas seladas nunca saíram deste telefone, então ficam. Todo o resto vai embora, de vez.",
    "wu.title": "ESCREVA PRA GENTE",
    "wu.intro": "Todo mundo aqui recebe uma carta. A gente também — conte qualquer coisa.",
    "wu.ph": "escreva pra gente…",
    "wu.addrLabel": "PARA ONDE RESPONDER — OPCIONAL",
    "wu.addrPh": "um endereço, se quiser resposta",
    "wu.addrHint": "Deixe em branco e isto fica anônimo, como tudo mais aqui — mas aí não temos como responder.",
    "wu.fail": "NÃO SAIU. TENTE DAQUI A POUCO.",
    "wu.send": "ENTREGUE A {wren}",
