    /* ── help / write-to-us ── */
    "hp.title": "CARA KERJANYA",
    "hp.intro": "Hampir semua pertanyaan di sini sebenarnya aturan yang belum ada yang memberitahumu. Jadi — aturannya.",
    "hp.q1": "Bagaimana sebuah surat menemukan seseorang?",
    "hp.a1": "Tak ada yang kamu tulis disiarkan. {wren} membaca caramu menulis — iramanya, bentuk kalimatnya, kata-kata yang kamu pilih — dan membawa suratmu ke orang asing yang tulisannya paling dekat dengan tulisanmu. Kamu dicocokkan lewat suara, bukan usia, lokasi, atau foto.",
    "hp.q2": "Kenapa aku tak bisa melihat siapa yang menulis ini?",
    "hp.a2": "Karena kalian belum saling mendapatkan nama, dan begitu juga orang lain. Semua di sini anonim sampai dua orang memutuskan sebaliknya.",
    "hp.q3": "Bagaimana nama dipertukarkan?",
    "hp.a3": "Sejak lima surat masing-masing, salah satu dari kalian boleh menyertakan nama. Tak terjadi apa-apa sampai yang lain melakukan hal yang sama — lalu {wren} membawa keduanya sekaligus. Kalau salah satu tak pernah menandatangani, kalian tetap orang asing yang indah, dan itu tak apa.",
    "hp.q4": "Apa itu auraku?",
    "hp.a4": "Sembilan sinyal dalam tulisanmu — cara kamu membuka, seberapa panjang barismu, di mana kamu menaruh perasaan. Masing-masing hanya terkunci saat ada cukup bukti untuk memercayainya, itu sebabnya ia terisi perlahan dan tak ada yang diklaim terlalu dini.",
    "hp.q5": "Apakah ada yang membaca halaman tersegelku?",
    "hp.a5": "Tidak, dan bukan dalam arti yang dimaksud kebanyakan app. Jurnal tersegelmu tak pernah meninggalkan ponsel ini. Ia tak diunggah, tak dicadangkan ke kami, dan sengaja ditinggalkan sepenuhnya dari pencocokan — jadi tak mungkin sampai ke orang asing bahkan secara tak sengaja. {wren} juga tak membacanya.",
    "hp.q6": "Kenapa semuanya begitu lambat?",
    "hp.a6": "Tak ada yang diperlambat di sini. {wren} berangkat detik kamu menekan kirim. Yang butuh berhari-hari adalah orang di ujung sana, menjalani hidupnya — dan itulah produknya, bukan penundaan yang bisa kami jual untuk kamu lewati.",
    "hp.q7": "Ada yang kejam. Apa yang harus kulakukan?",
    "hp.a7": "Buka ⋯ pada suratnya. Laporkan mengirimnya ke kami; blokir menutup jalan dua arah dan bisa dibatalkan di Pengaturan, di Diblokir & dilaporkan. Laporan berulang mengeluarkan seorang penulis dari Kindredly.",
    "hp.q8": "Apa yang terjadi jika aku menghapus akunku?",
    "hp.a8": "Suratmu tetap ada di dunia, tanpa tanda tangan — seorang kerabat menyimpan yang kamu tulis untuknya, dan tak ada yang menuntun kembali kepadamu. Halaman tersegelmu tak pernah meninggalkan ponsel ini, jadi tetap ada. Selebihnya hilang, selamanya.",
    "wu.title": "TULIS UNTUK KAMI",
    "wu.intro": "Semua orang di sini menerima surat. Kami juga — ceritakan apa saja.",
    "wu.ph": "tulis untuk kami…",
    "wu.addrLabel": "KE MANA KAMI MEMBALAS — OPSIONAL",
    "wu.addrPh": "sebuah alamat, kalau kamu mau jawaban",
    "wu.addrHint": "Biarkan kosong dan ini tetap anonim, seperti semua yang lain di sini — tapi kami jadi tak bisa membalas.",
