    "jd.keep": "La garder",
    "jd.tear": "L'arracher",
    "jd.fail": "Impossible de l'envoyer",
    "jd.failBody": "Cette ligne est restée. Réessaie.",
    "jd.signup.reason": "Cette ligne est la seule chose qui quitte la pièce scellée, alors il lui faut un compte pour voyager. La page elle-même reste ici de toute façon.",
    "hp.title": "COMMENT ÇA MARCHE",
    "hp.intro": "La plupart des questions ici sont en fait une règle que personne ne t'a encore dite. Donc — les règles.",
    "hp.q1": "Comment une lettre trouve-t-elle quelqu'un ?",
    "hp.a1": "Rien de ce que tu écris n'est diffusé. {wren} lit comment tu écris — le rythme, la forme des phrases, les mots que tu vas chercher — et porte ta lettre à l'inconnu dont l'écriture est la plus proche de la tienne. On t'apparie par la voix, jamais par l'âge, le lieu ou une photo.",
    "hp.q2": "Pourquoi je ne vois pas qui a écrit ça ?",
    "hp.a2": "Parce que vous n'avez pas encore mérité vos noms, et personne d'autre non plus. Tout le monde ici est anonyme jusqu'à ce que deux personnes en décident autrement.",
    "hp.q3": "Comment les noms s'échangent-ils ?",
    "hp.a3": "À partir de cinq lettres chacun, l'un ou l'autre peut glisser son nom. Rien ne se passe tant que l'autre ne fait pas pareil — alors {wren} porte les deux d'un coup. Si l'un de vous ne signe jamais, vous restez de charmants inconnus, et c'est permis.",
    "hp.q4": "C'est quoi, mon aura ?",
    "hp.a4": "Neuf signaux dans ton écriture — comment tu ouvres, la longueur de tes lignes, où tu mets le sentiment. Chacun ne se fixe que quand il y a assez de preuves pour s'y fier, c'est pourquoi ça se remplit lentement et que rien n'est affirmé trop tôt.",
    "hp.q5": "Quelqu'un lit-il mes pages scellées ?",
    "hp.a5": "Non, et pas au sens où la plupart des apps l'entendent. Ton journal scellé ne quitte jamais ce téléphone. Il n'est pas envoyé, pas sauvegardé chez nous, et délibérément tenu à l'écart de l'appariement — il ne peut donc atteindre un inconnu, même par accident. {wren} ne les lit pas non plus.",
    "hp.q6": "Pourquoi tout est si lent ?",
    "hp.a6": "Rien ici n'est bridé. {wren} part à la seconde où tu appuies sur envoyer. Ce qui prend des jours, c'est la personne à l'autre bout, qui vit sa vie — et c'est ça le produit, pas un délai qu'on pourrait te vendre.",
    "hp.q7": "Quelqu'un a été cruel. Je fais quoi ?",
    "hp.a7": "Ouvre le ⋯ sur sa lettre. Signaler nous l'envoie ; bloquer ferme la route dans les deux sens et s'annule dans les Réglages, sous Bloqués et signalés. Des signalements répétés retirent quelqu'un de Kindredly.",
    "hp.q8": "Que se passe-t-il si je supprime mon compte ?",
    "hp.a8": "Tes lettres restent dans le monde, sans signature — un semblable garde ce que tu lui as écrit, et rien ne remonte à toi. Tes pages scellées n'ont jamais quitté ce téléphone, alors elles restent. Tout le reste s'en va, pour de bon.",
    "wu.title": "ÉCRIS-NOUS",
    "wu.intro": "Tout le monde ici reçoit une lettre. Nous aussi — dis-nous ce que tu veux.",
    "wu.ph": "écris-nous…",
