    "ks.why.first-flight": "Mein erster echter Botengang. Du hast etwas geschrieben, und ich habe es hinaus in die Welt getragen.",
    "ks.why.night-flight": "Du hast mir einen Brief gegeben, während alle anderen schliefen. Die mag ich am liebsten.",
    "ks.why.early-bird-flight": "Raus vor dem Licht. Du warst schon eine Weile wach, glaube ich.",
    "ks.why.same-hour-twice": "Jetzt zweimal, zur selben Stunde. Ich weiß langsam, wann ich an der Tür warten soll.",
    "ks.why.favorite-hour": "Das ist unsere Stunde. Ich bin nicht mehr überrascht davon.",
    "ks.why.favorite-day": "Dieser Tag, mehr als jeder andere. Ich halte ihn mir jetzt ganz frei.",
    "ks.why.late-return": "Ich kam lange nach Einbruch der Dunkelheit zurück. Jemand war noch wach und dachte an dich.",
    "ks.why.first-reply": "Das erste Mal, dass ich etwas nach Hause gebracht habe, statt es nur wegzutragen.",
    "ks.why.first-morning-reply": "Es wartete schon, als der Tag anfing. Ich habe es direkt herübergeflogen.",
    "ks.why.first-midnight-reply": "Sie haben um Mitternacht zurückgeschrieben. Ich habe nicht bis zum Morgen gewartet.",
    "ks.why.word-came-back": "Eins deiner Wörter kam in der Handschrift von jemand anderem nach Hause.",
    "ks.why.first-thread": "Aus einem Brief wurde ein Briefwechsel. Das passiert nicht jedes Mal.",
    "ks.why.first-turn-back": "Du hast wieder geschrieben, nachdem sie geantwortet hatten. Da hört es auf, eine Antwort zu sein, und wird ein Gespräch.",
    "ks.why.five-letters-deep": "Fünf in jede Richtung. Von hier an kann jeder von euch einen Namen beilegen.",
    "ks.why.you-signed-first": "Du bist vorangegangen. Das hat etwas gekostet.",
    "ks.why.they-signed-first": "Sie sind vorangegangen — sie haben sich entschieden, von dir gekannt zu werden.",
    "ks.why.name-seal": "Das erste Mal, dass du deinen Namen in einen Brief gesiegelt hast.",
    "ks.why.first-kindred": "Zwei Namen haben sich in meinem Schnabel gekreuzt. Dafür trage ich Briefe.",
    "ks.why.three-kindreds": "Drei Menschen kennen jetzt deinen Namen. Ich habe sie alle vorgestellt.",
    "ks.why.five-kindreds": "Fünf. In deinem Himmel ist eine kleine Menge.",
    "ks.why.longest-thread": "Die längste Strecke, die ich je zwischen zwei Menschen geflogen bin. Und es geht weiter.",
    "ks.why.word-spotted": "Du greifst immer wieder nach diesem. Ich bemerke es inzwischen vor dir.",
    "ks.why.first-voice-letter": "Das erste Mal, dass das, was ich trug, deine Stimme enthielt, nicht nur deine Hand.",
    "ks.why.first-sealed-page": "Du hast mir etwas zum Aufbewahren gegeben statt zum Ausliefern. Es hat das Haus nie verlassen.",
    "ks.why.first-photo-kept": "Ein Bild, versiegelt. Wörter sind nicht das Einzige, was sich zu behalten lohnt.",
    "ks.why.first-drifted-line": "Eine Zeile aus deinen versiegelten Seiten wollte hinaus. Ich habe sie gelassen.",
    "ks.why.10-letters-carried": "Zehn Briefe. Meine Flügel kennen jetzt den Weg.",
    "ks.why.50-letters-carried": "Fünfzig. An manche erinnerst du dich nicht einmal mehr.",
    "ks.why.100-letters-carried": "Hundert Briefe getragen. Das ist eine Menge von jemandes Leben.",
    "ks.why.first-anniversary": "Ein Jahr davon. Ich war ein Ei, als wir angefangen haben.",
