    "sc.journalTitle": "Tagebuch",
    "jd.driftThis": "DIESE DAVONTREIBEN LASSEN",
    "jd.driftOne": "EINE ZEILE DAVONTREIBEN LASSEN",
    "jd.delete": "LÖSCHEN",
    "jd.tearSample.title": "Dieses Beispiel herausreißen?",
    "jd.tearSample.body": "Es ist eins von uns, nicht deins — es hört nur auf, hier zu erscheinen.",
    "jd.tearPage.title": "Diese Seite herausreißen?",
    "jd.tearPage.body": "Sie verschwindet aus dem versiegelten Zimmer. Eine Zeile, die schon davongetrieben ist, bleibt draußen in der Welt.",
    "jd.keep": "Behalten",
    "jd.tear": "Herausreißen",
    "jd.fail": "Konnte sie nicht hinausschicken",
    "jd.failBody": "Die Zeile ist geblieben. Versuch es noch einmal.",
    "jd.signup.reason": "Diese Zeile ist das Einzige, was das versiegelte Zimmer verlässt, also braucht sie ein Konto, unter dem sie reist. Die Seite selbst bleibt so oder so hier.",
    "hp.title": "SO FUNKTIONIERT ES",
    "hp.intro": "Die meisten Fragen hier sind eigentlich eine Regel, die dir noch niemand gesagt hat. Also — die Regeln.",
    "hp.q1": "Wie findet ein Brief jemanden?",
    "hp.a1": "Nichts, was du schreibst, wird gesendet wie eine Sendung. {wren} liest, wie du schreibst — Rhythmus, Satzform, die Wörter, nach denen du greifst — und trägt deinen Brief zu dem Fremden, dessen Schreiben deinem am nächsten liegt. Du wirst nach der Stimme zugeordnet, nie nach Alter, Ort oder einem Foto.",
    "hp.q2": "Warum sehe ich nicht, wer das geschrieben hat?",
    "hp.a2": "Weil ihr euch die Namen noch nicht verdient habt, und das hat sonst auch niemand. Alle hier sind anonym, bis zwei Menschen sich anders entscheiden.",
    "hp.q3": "Wie werden Namen getauscht?",
    "hp.a3": "Ab fünf Briefen von jedem darf einer von euch seinen Namen beilegen. Nichts passiert, bis der andere dasselbe tut — dann trägt {wren} beide auf einmal hinüber. Wenn einer von euch nie unterschreibt, bleibt ihr reizende Fremde, und das ist erlaubt.",
    "hp.q4": "Was ist meine Aura?",
    "hp.a4": "Neun Signale in deinem Schreiben — wie du beginnst, wie lang deine Zeilen laufen, wo du Gefühl hinsetzt. Jedes steht erst fest, wenn genug Belege da sind, um ihm zu trauen — deshalb füllt es sich langsam, und deshalb wird nichts zu früh behauptet.",
    "hp.q5": "Liest jemand meine versiegelten Seiten?",
    "hp.a5": "Nein, und nicht so, wie die meisten Apps das meinen. Dein versiegeltes Tagebuch verlässt dieses Telefon nie. Es wird nicht hochgeladen, nicht bei uns gesichert und absichtlich ganz aus dem Zuordnen herausgehalten — es kann also nicht einmal aus Versehen einen Fremden erreichen. {wren} liest sie auch nicht.",
    "hp.q6": "Warum ist alles so langsam?",
    "hp.a6": "Nichts hier wird gedrosselt. {wren} fliegt in der Sekunde los, in der du auf Senden drückst. Was Tage dauert, ist der Mensch am anderen Ende, der sein Leben lebt — und das ist das Produkt, keine Verzögerung, aus der wir dich herauskaufen lassen könnten.",
    "hp.q7": "Jemand war grausam. Was tue ich?",
    "hp.a7": "Öffne das ⋯ auf dem Brief. Melden schickt ihn an uns; Blockieren schließt die Straße in beide Richtungen und lässt sich in den Einstellungen unter Blockiert & gemeldet rückgängig machen. Wiederholte Meldungen entfernen jemanden aus Kindredly.",
    "hp.q8": "Was passiert, wenn ich mein Konto lösche?",
    "hp.a8": "Deine Briefe bleiben draußen in der Welt, ohne Unterschrift — Seelenverwandte behalten, was du ihnen geschrieben hast, und nichts führt zu dir zurück. Deine versiegelten Seiten haben dieses Telefon nie verlassen, also bleiben sie. Alles andere geht, für immer.",
