    "ks.why.first-flight": "La mia prima vera commissione. Hai scritto qualcosa, e io l'ho portato fuori nel mondo.",
    "ks.why.night-flight": "Mi hai dato una lettera mentre tutti gli altri dormivano. Quelle le preferisco.",
    "ks.why.early-bird-flight": "Fuori prima della luce. Eri sveglio da un po', credo.",
    "ks.why.same-hour-twice": "Due volte ormai, alla stessa ora. Comincio a sapere quando aspettare vicino alla porta.",
    "ks.why.favorite-hour": "Questa è la nostra ora. Ho smesso di sorprendermi.",
    "ks.why.favorite-day": "Questo giorno, più di ogni altro. Adesso lo tengo tutto libero.",
    "ks.why.late-return": "Sono tornata molto dopo il buio. Qualcuno era ancora sveglio, a pensare a te.",
    "ks.why.first-reply": "La prima volta che ho riportato qualcosa a casa invece di portarlo solo via.",
    "ks.why.first-morning-reply": "Aspettava già quando è iniziata la giornata. L'ho portata dritta da te.",
    "ks.why.first-midnight-reply": "Hanno risposto a mezzanotte. Non ho aspettato il mattino.",
    "ks.why.word-came-back": "Una delle tue parole è tornata a casa nella scrittura di qualcun altro.",
    "ks.why.first-thread": "Una lettera è diventata una corrispondenza. Non succede ogni volta.",
    "ks.why.first-turn-back": "Hai scritto di nuovo dopo la loro risposta. È lì che smette di essere una risposta e diventa una conversazione.",
    "ks.why.five-letters-deep": "Cinque per parte. Da qui, ognuno di voi può allegare un nome.",
    "ks.why.you-signed-first": "Hai fatto il primo passo. Ci è voluto qualcosa.",
    "ks.why.they-signed-first": "Hanno fatto il primo passo — hanno scelto di farsi conoscere da te.",
    "ks.why.name-seal": "La prima volta che hai sigillato il tuo nome in una lettera.",
    "ks.why.first-kindred": "Due nomi si sono incrociati nel mio becco. È per questo che porto lettere.",
    "ks.why.three-kindreds": "Tre persone ora conoscono il tuo nome. Le ho presentate tutte io.",
    "ks.why.five-kindreds": "Cinque. C'è una piccola folla nel tuo cielo.",
    "ks.why.longest-thread": "La strada più lunga che abbia mai volato tra due persone. E continua.",
    "ks.why.word-spotted": "Continui a cercare questa. Ho iniziato a notarla prima di te.",
    "ks.why.first-voice-letter": "La prima volta che ciò che portavo aveva dentro la tua voce, non solo la tua mano.",
    "ks.why.first-sealed-page": "Mi hai dato qualcosa da custodire invece che da consegnare. Non ha mai lasciato casa.",
    "ks.why.first-photo-kept": "Un'immagine, sigillata. Le parole non sono l'unica cosa che vale la pena conservare.",
    "ks.why.first-drifted-line": "Una riga delle tue pagine sigillate ha chiesto di uscire. L'ho lasciata.",
    "ks.why.10-letters-carried": "Dieci lettere. Le mie ali ormai conoscono la strada.",
    "ks.why.50-letters-carried": "Cinquanta. Alcune non ti ricordi nemmeno di averle scritte.",
    "ks.why.100-letters-carried": "Cento lettere portate. È un bel pezzo della vita di qualcuno.",
    "ks.why.first-anniversary": "Un anno di questo. Ero un uovo quando abbiamo cominciato.",
