    "jd.tear": "Strappala",
    "jd.fail": "Impossibile mandarla fuori",
    "jd.failBody": "Quella riga è rimasta ferma. Riprova.",
    "jd.signup.reason": "Questa riga è l'unica cosa che lascia la stanza sigillata, quindi le serve un account con cui viaggiare. La pagina in sé resta qui comunque.",
    "hp.title": "COME FUNZIONA",
    "hp.intro": "La maggior parte delle domande qui in realtà è una regola che nessuno ti ha ancora detto. Quindi — le regole.",
    "hp.q1": "Come fa una lettera a trovare qualcuno?",
    "hp.a1": "Niente di ciò che scrivi viene trasmesso. {wren} legge come scrivi — ritmo, forma delle frasi, le parole che vai a cercare — e porta la tua lettera allo sconosciuto la cui scrittura è più vicina alla tua. Vieni abbinato per voce, mai per età, luogo o una foto.",
    "hp.q2": "Perché non vedo chi ha scritto questo?",
    "hp.a2": "Perché non vi siete ancora guadagnati i nomi a vicenda, e nessun altro l'ha fatto. Tutti qui sono anonimi finché due persone non decidono altrimenti.",
    "hp.q3": "Come si scambiano i nomi?",
    "hp.a3": "Da cinque lettere ciascuno, uno di voi può allegare il proprio nome. Non succede niente finché l'altro non fa lo stesso — allora {wren} li porta entrambi insieme. Se uno di voi non firma mai, restate adorabili sconosciuti, ed è permesso.",
    "hp.q4": "Cos'è la mia aura?",
    "hp.a4": "Nove segnali nella tua scrittura — come apri, quanto corrono le tue righe, dove metti il sentimento. Ognuno si fissa solo quando ci sono abbastanza prove per fidarsi, ecco perché si riempie lentamente e perché niente viene affermato presto.",
    "hp.q5": "Qualcuno legge le mie pagine sigillate?",
    "hp.a5": "No, e non nel senso che intendono la maggior parte delle app. Il tuo diario sigillato non lascia mai questo telefono. Non viene caricato, non viene salvato da noi, ed è deliberatamente tenuto fuori dagli abbinamenti — quindi non può raggiungere uno sconosciuto nemmeno per sbaglio. Nemmeno {wren} le legge.",
    "hp.q6": "Perché è tutto così lento?",
    "hp.a6": "Niente qui è rallentato. {wren} parte nel secondo in cui premi invia. Quello che ci mette giorni è la persona dall'altra parte, che vive la sua vita — e quello è il prodotto, non un ritardo da cui potremmo venderti la scorciatoia.",
    "hp.q7": "Qualcuno è stato crudele. Cosa faccio?",
    "hp.a7": "Apri il ⋯ sulla sua lettera. Segnala ce la manda; blocca chiude la strada in entrambe le direzioni e si può annullare nelle Impostazioni, sotto Bloccati e segnalati. Segnalazioni ripetute rimuovono qualcuno da Kindredly.",
    "hp.q8": "Cosa succede se cancello il mio account?",
    "hp.a8": "Le tue lettere restano là fuori nel mondo, senza firma — un affine tiene ciò che gli hai scritto, e niente riconduce a te. Le tue pagine sigillate non hanno mai lasciato questo telefono, quindi restano. Tutto il resto se ne va, per sempre.",
    "wu.title": "SCRIVICI",
    "wu.intro": "Tutti gli altri qui ricevono una lettera. Anche noi — raccontaci qualsiasi cosa.",
    "wu.ph": "scrivici…",
