    "jd.tear": "破る",
    "jd.fail": "送り出せませんでした",
    "jd.failBody": "その一行はここに残っています。もう一度どうぞ。",
    "jd.signup.reason": "この一行は、封印の部屋を出る唯一のもの。だから旅するためのアカウントが必要です。ページ自体は、どちらにしてもここに残ります。",
    "hp.title": "しくみ",
    "hp.intro": "ここでの疑問のほとんどは、まだ誰も教えてくれていないルールです。なので — ルールを。",
    "hp.q1": "手紙はどうやって誰かを見つけるの？",
    "hp.a1": "書いたものが一斉配信されることはありません。{wren}があなたの書き方 — リズム、文の形、手を伸ばす言葉 — を読み、あなたの文章にいちばん近い書き方をする見知らぬ人へ手紙を運びます。年齢、場所、写真ではなく、声でマッチングされます。",
    "hp.q2": "なぜ誰が書いたのかわからないの？",
    "hp.a2": "まだ互いの名前を得ていないからです。他の誰もそうです。ここでは、ふたりがそうしないと決めるまで、全員が匿名です。",
    "hp.q3": "名前はどうやって交わすの？",
    "hp.a3": "互いに五通ずつ書いたら、どちらからでも名前を添えられます。相手が同じことをするまで何も起きません — そのとき{wren}が両方の名前を一度に運びます。どちらかが名乗らなければ、素敵な他人のまま。それも許されています。",
    "hp.q4": "オーラって何？",
    "hp.a4": "あなたの文章にある九つの信号 — 書き出し方、行の長さ、気持ちをどこに置くか。それぞれ、信じられるだけの証拠がそろったときにだけ確定します。だからゆっくり埋まり、早すぎる断定はしません。",
    "hp.q5": "封印したページを誰かが読む？",
    "hp.a5": "いいえ。多くのアプリが言う意味でも、読みません。封印した日記は、このスマホの外に出ません。アップロードされず、わたしたちにバックアップされず、マッチングからも意図的に完全に外しています — だから、事故でも見知らぬ人に届くことはありません。{wren}も読みません。",
    "hp.q6": "なぜこんなに遅いの？",
    "hp.a6": "ここでは何も遅らせていません。{wren}は送信を押した瞬間に出発します。日数がかかるのは、向こう側にいる人が自分の人生を生きているから — それが製品そのもので、お金で解消できる遅延ではありません。",
    "hp.q7": "誰かがひどいことを言った。どうすればいい？",
    "hp.a7": "その手紙の ⋯ を開いてください。「通報」でわたしたちに届き、「ブロック」で道が双方向に閉じます。ブロックは設定の「ブロックと通報」から解除できます。通報が重なった書き手はKindredlyから取り除かれます。",
    "hp.q8": "アカウントを削除するとどうなる？",
    "hp.a8": "あなたの手紙は、名前なしで世界に残ります — 仲間はあなたが書いたものを持ち続け、何もあなたにはたどり着きません。封印したページはこのスマホから出たことがないので、そのまま残ります。それ以外はすべて、永久に消えます。",
    "wu.title": "わたしたちに書く",
    "wu.intro": "ここでは誰もが手紙をもらいます。わたしたちも — 何でも伝えてください。",
