    "jd.tearSample.title": "이 샘플을 찢을까요?",
    "jd.tearSample.body": "당신 것이 아니라 우리 거예요 — 여기 더 안 보일 뿐이에요.",
    "jd.tearPage.title": "이 페이지를 찢을까요?",
    "jd.tearPage.body": "봉인의 방에서 사라져요. 이미 띄운 한 줄은 세상에 남아요.",
    "jd.keep": "두기",
    "jd.tear": "찢기",
    "jd.fail": "내보내지 못했어요",
    "jd.failBody": "그 줄은 그대로 있어요. 다시 시도해 주세요.",
    "jd.signup.reason": "이 한 줄은 봉인의 방을 떠나는 유일한 것이라, 여행할 계정이 필요해요. 페이지 자체는 어차피 여기 남아요.",
    "hp.title": "작동 방식",
    "hp.intro": "여기서 생기는 질문 대부분은 아직 아무도 말해 주지 않은 규칙이에요. 그래서 — 규칙을요.",
    "hp.q1": "편지는 어떻게 누군가를 찾나요?",
    "hp.a1": "당신이 쓴 건 아무것도 뿌려지지 않아요. {wren}이(가) 당신의 글쓰기 — 리듬, 문장 모양, 손이 가는 단어 — 를 읽고, 당신의 글에 가장 가까운 글을 쓰는 모르는 사람에게 편지를 날라요. 나이, 위치, 사진이 아니라 목소리로 이어져요.",
    "hp.q2": "왜 누가 썼는지 볼 수 없나요?",
    "hp.a2": "아직 서로의 이름을 얻지 못했으니까요. 다른 누구도 마찬가지예요. 여기선 두 사람이 달리 정하기 전까지 모두가 익명이에요.",
    "hp.q3": "이름은 어떻게 주고받나요?",
    "hp.a3": "서로 다섯 통씩 쓰고 나면 누구든 이름을 동봉할 수 있어요. 상대가 똑같이 하기 전엔 아무 일도 일어나지 않아요 — 그때 {wren}이(가) 두 이름을 한꺼번에 건네요. 한쪽이 끝내 서명하지 않으면 멋진 타인으로 남아요. 그것도 괜찮아요.",
    "hp.q4": "아우라가 뭔가요?",
    "hp.a4": "당신의 글에 있는 아홉 가지 신호 — 어떻게 여는지, 줄이 얼마나 긴지, 감정을 어디에 두는지. 각각은 믿을 만한 증거가 충분할 때만 확정돼요. 그래서 천천히 채워지고, 성급하게 단정하지 않아요.",
    "hp.q5": "봉인한 페이지를 누가 읽나요?",
    "hp.a5": "아니요. 다른 앱들이 말하는 그런 식으로도 아니에요. 봉인한 일기는 이 휴대폰을 떠나지 않아요. 업로드되지 않고, 저희 쪽에 백업되지 않고, 매칭에서도 일부러 완전히 빼 뒀어요 — 그래서 실수로라도 모르는 사람에게 닿을 수 없어요. {wren}도 읽지 않아요.",
    "hp.q6": "왜 이렇게 느린가요?",
    "hp.a6": "여기선 아무것도 늦추지 않아요. {wren}은(는) 보내기를 누르는 순간 떠나요. 며칠이 걸리는 건 저편에 있는 사람이 자기 삶을 살고 있어서예요 — 그게 바로 이 제품이지, 돈으로 없앨 수 있는 지연이 아니에요.",
    "hp.q7": "누가 잔인하게 굴었어요. 어떻게 하죠?",
    "hp.a7": "그 편지의 ⋯ 를 여세요. '신고'는 저희에게 보내고, '차단'은 길을 양쪽으로 닫아요. 차단은 설정의 '차단 및 신고'에서 되돌릴 수 있어요. 신고가 거듭된 사람은 Kindredly에서 제거돼요.",
    "hp.q8": "계정을 삭제하면 어떻게 되나요?",
    "hp.a8": "당신의 편지는 서명 없이 세상에 남아요 — 인연은 당신이 쓴 것을 간직하고, 아무것도 당신에게 되돌아오지 않아요. 봉인한 페이지는 이 휴대폰을 떠난 적이 없으니 그대로 남아요. 그 밖의 모든 것은 영원히 사라져요.",
    "wu.title": "저희에게 쓰기",
    "wu.intro": "여기선 모두가 편지를 받아요. 저희도요 — 무엇이든 말해 주세요.",
